 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    eight = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    r0, r1 = min(r for r, c in eight), max(r for r, c in eight)
    c0, c1 = min(c for r, c in eight), max(c for r, c in eight)
    kr0, kr1 = min(r for r, c in marks), max(r for r, c in marks)
    kc0, kc1 = min(c for r, c in marks), max(c for r, c in marks)
    kh, kw = kr1 - kr0 + 1, kc1 - kc0 + 1
    bh, bw = r1 - r0 + 1, c1 - c0 + 1
    if bh % kh or bw % kw or bh // kh != bw // kw:
        raise ValueError("marker and silhouette scales do not align")
    scale = bh // kh
    pattern = [[0] * kw for _ in range(kh)]
    for r, c in marks:
        pattern[r - kr0][c - kc0] = grid[r][c]
    rotated = [[pattern[kh - 1 - c][r] for c in range(kh)] for r in range(kw)]
    if len(rotated) != (r1 - r0 + 1) // scale or len(rotated[0]) != (c1 - c0 + 1) // scale:
        raise ValueError("rotated marker dimensions mismatch")
    for mr, row in enumerate(rotated):
        for mc, color in enumerate(row):
            for dr in range(scale):
                for dc in range(scale):
                    rr, cc = r0 + mr * scale + dr, c0 + mc * scale + dc
                    if grid[rr][cc] == 8:
                        if color == 0:
                            raise ValueError("marker/silhouette mismatch")
                        out[rr][cc] = color
                    elif color != 0:
                        raise ValueError("marker/silhouette mismatch")
    return out
"
